"""Returns the word with the highest occurence given a word sequence

    :param prev_seq:
    :param counts:
    :param N:
    :returns max_successor

    """
def next_word_max_solution(prev_seq: Any, counts: Any, N: Any) -> object {
    token_seq = " ".join(prev_seq.split()[-(N - 1):]);
    max_successor = max(counts[token_seq].items(), key=lambda (k: Any) { k[1]; })[0];
    return max_successor;
}
